def compute(vars):
    revenue_2017 = vars["v1"]
    increase_percent = vars["v2"]
    growth_factor = 1 + increase_percent / 100
    if growth_factor == 0:
        return None
    revenue_2016 = revenue_2017 / growth_factor
    return {
        "value": revenue_2016,
        "trace": {
            "revenue_2017": revenue_2017,
            "increase_percent": increase_percent,
            "growth_factor": growth_factor,
            "output_meta": {
                "currency": "USD",
                "scale": "billion",
                "unit": None
            }
        }
    }
